CREATE TABLE schools (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_uuid CHAR(36) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, logo_path VARCHAR(500) NULL, address TEXT NULL, website VARCHAR(500) NULL, whatsapp VARCHAR(50) NULL, email VARCHAR(255) NULL, instagram VARCHAR(255) NULL, branding_json LONGTEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY admins_school_email_unique (school_id,email), CONSTRAINT admins_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, short_name VARCHAR(100) NOT NULL, personality_title VARCHAR(255) NULL, description TEXT NULL, color_json VARCHAR(500) NULL, mascot_path VARCHAR(500) NULL, skills_json LONGTEXT NULL, result_copy TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY programs_school_short_name_unique (school_id,short_name), KEY programs_school_active_order (school_id,is_active,sort_order), CONSTRAINT programs_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE program_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, path VARCHAR(500) NOT NULL, media_type VARCHAR(50) NOT NULL, caption VARCHAR(500) NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY program_media_program_order (program_id,sort_order), CONSTRAINT program_media_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE program_careers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY program_careers_program_order (program_id,sort_order), CONSTRAINT program_careers_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quizzes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', allow_retry TINYINT(1) NOT NULL DEFAULT 1, randomize_questions TINYINT(1) NOT NULL DEFAULT 0, randomize_answers TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY quizzes_school_status (school_id,status), CONSTRAINT quizzes_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quiz_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quiz_id BIGINT UNSIGNED NOT NULL, version_number INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', published_at DATETIME NULL, created_at DATETIME NOT NULL, UNIQUE KEY quiz_versions_quiz_number_unique (quiz_id,version_number), CONSTRAINT quiz_versions_quiz_fk FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quiz_version_id BIGINT UNSIGNED NOT NULL, prompt TEXT NOT NULL, help_text TEXT NULL, sort_order INT UNSIGNED NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY questions_version_order_unique (quiz_version_id,sort_order), CONSTRAINT questions_version_fk FOREIGN KEY (quiz_version_id) REFERENCES quiz_versions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE question_options (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_id BIGINT UNSIGNED NOT NULL, option_text TEXT NOT NULL, sort_order INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY question_options_question_order_unique (question_id,sort_order), CONSTRAINT question_options_question_fk FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE option_weights (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_option_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NOT NULL, weight DECIMAL(10,2) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY option_weights_option_program_unique (question_option_id,program_id), CONSTRAINT option_weights_option_fk FOREIGN KEY (question_option_id) REFERENCES question_options(id) ON DELETE RESTRICT, CONSTRAINT option_weights_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, quiz_id BIGINT UNSIGNED NULL, name VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', starts_at DATETIME NULL, ends_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY campaigns_school_status (school_id,status), CONSTRAINT campaigns_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT, CONSTRAINT campaigns_quiz_fk FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE smart_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, campaign_id BIGINT UNSIGNED NULL, name VARCHAR(255) NOT NULL, alias VARCHAR(255) NOT NULL UNIQUE, source VARCHAR(100) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, scan_count BIGINT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY smart_links_campaign_active (campaign_id,is_active), CONSTRAINT smart_links_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT, CONSTRAINT smart_links_campaign_fk FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE participants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, public_uuid CHAR(36) NOT NULL UNIQUE, full_name VARCHAR(255) NOT NULL, origin_school VARCHAR(255) NULL, class_name VARCHAR(100) NULL, phone VARCHAR(50) NULL, marketing_consent TINYINT(1) NOT NULL DEFAULT 0, marketing_consent_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY participants_school_phone (school_id,phone), CONSTRAINT participants_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, participant_id BIGINT UNSIGNED NULL, campaign_id BIGINT UNSIGNED NULL, quiz_version_id BIGINT UNSIGNED NOT NULL, visitor_uuid CHAR(36) NOT NULL, attempt_uuid CHAR(36) NOT NULL UNIQUE, source VARCHAR(100) NULL, submitted_at DATETIME NULL, created_at DATETIME NOT NULL, KEY attempts_version_submitted (quiz_version_id,submitted_at), KEY attempts_participant_created (participant_id,created_at), CONSTRAINT attempts_participant_fk FOREIGN KEY (participant_id) REFERENCES participants(id) ON DELETE RESTRICT, CONSTRAINT attempts_campaign_fk FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE RESTRICT, CONSTRAINT attempts_version_fk FOREIGN KEY (quiz_version_id) REFERENCES quiz_versions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE responses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attempt_id BIGINT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, question_option_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY responses_attempt_question_unique (attempt_id,question_id), CONSTRAINT responses_attempt_fk FOREIGN KEY (attempt_id) REFERENCES attempts(id) ON DELETE RESTRICT, CONSTRAINT responses_question_fk FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE RESTRICT, CONSTRAINT responses_option_fk FOREIGN KEY (question_option_id) REFERENCES question_options(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attempt_id BIGINT UNSIGNED NOT NULL UNIQUE, dominant_program_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, CONSTRAINT results_attempt_fk FOREIGN KEY (attempt_id) REFERENCES attempts(id) ON DELETE RESTRICT, CONSTRAINT results_program_fk FOREIGN KEY (dominant_program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE result_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, result_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NOT NULL, raw_score DECIMAL(12,2) NOT NULL, normalized_percentage DECIMAL(7,4) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY result_scores_result_program_unique (result_id,program_id), CONSTRAINT result_scores_result_fk FOREIGN KEY (result_id) REFERENCES results(id) ON DELETE RESTRICT, CONSTRAINT result_scores_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE campaign_stats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campaign_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NULL, metric_date DATE NOT NULL, participant_count BIGINT UNSIGNED NOT NULL DEFAULT 0, result_count BIGINT UNSIGNED NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, UNIQUE KEY campaign_stats_scope_date_unique (campaign_id,program_id,metric_date), CONSTRAINT campaign_stats_campaign_fk FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE RESTRICT, CONSTRAINT campaign_stats_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE monitor_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL UNIQUE, campaign_id BIGINT UNSIGNED NULL, rotation_seconds INT UNSIGNED NOT NULL DEFAULT 5, polling_seconds INT UNSIGNED NOT NULL DEFAULT 10, is_active TINYINT(1) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, CONSTRAINT monitor_settings_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT, CONSTRAINT monitor_settings_campaign_fk FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NULL, setting_key VARCHAR(255) NOT NULL, setting_value LONGTEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY settings_school_key_unique (school_id,setting_key), CONSTRAINT settings_school_fk FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
